/** Content-addressed AudioWorklet URL injected by the Vite build. */
declare const __SONARE_WORKLET_MODULE_URL__: string;

/** Application version injected by the Vite build, read from package.json. */
declare const __SONARE_APP_VERSION__: string;

/** Short commit the build was produced from; empty when the commit is unknown. */
declare const __SONARE_BUILD_COMMIT__: string;

/** ISO-8601 timestamp of the moment the bundle was built. */
declare const __SONARE_BUILD_TIME__: string;
